#!/usr/bin/env python3
"""Wrap monitoring/dashboards/*.json into one ConfigMap the Grafana sidecar loads.

Usage: python3 scripts/build-dashboard-configmap.py [--check]
--check exits non-zero if the committed ConfigMap is out of date (used in CI).
"""
import json
import pathlib
import sys

root = pathlib.Path(__file__).resolve().parent.parent
src = root / "monitoring" / "dashboards"
out = src / "dashboards-configmap.yaml"

lines = [
    "# Generated by scripts/build-dashboard-configmap.py. Edit the .json files, not this file.",
    "apiVersion: v1",
    "kind: ConfigMap",
    "metadata:",
    "  name: demo-app-dashboards",
    "  namespace: monitoring",
    "  labels:",
    '    grafana_dashboard: "1"',
    "data:",
]
for f in sorted(src.glob("*.json")):
    json.loads(f.read_text())  # fail early on invalid JSON
    lines.append(f"  {f.name}: |")
    lines += [("    " + l) if l else "" for l in f.read_text().rstrip("\n").split("\n")]
text = "\n".join(lines) + "\n"

if "--check" in sys.argv:
    if not out.exists() or out.read_text() != text:
        sys.exit("dashboards-configmap.yaml is out of date: run scripts/build-dashboard-configmap.py")
    print("dashboards-configmap.yaml is up to date")
else:
    out.write_text(text)
    print(f"wrote {out.relative_to(root)}")
